# Generated by astrona-cli's release workflow (.github/scripts/homebrew-formula.sh)
# for v0.4.3 — don't edit by hand, the next release overwrites it.
class Astrona < Formula
  desc "Local Kubernetes (kind) and QEMU lab environments: run, grade, tear down"
  homepage "https://github.com/astrona-io/astrona-cli"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  # Include the tools for both kind and QEMU labs. The user chooses and
  # starts the container engine (Docker or Podman) — see caveats.
  depends_on "cdrtools"
  depends_on "git"
  depends_on "kind"
  depends_on "kubernetes-cli"
  depends_on "oras"
  depends_on "qemu"

  on_macos do
    on_arm do
      url "https://github.com/astrona-io/astrona-cli/releases/download/v0.4.3/astrona-darwin-arm64"
      sha256 "de84d23c0e79461e07cfa0c9e43d5d5a062dc9d28c2101fbd49291a8d2bacab1"
    end
    on_intel do
      url "https://github.com/astrona-io/astrona-cli/releases/download/v0.4.3/astrona-darwin-amd64"
      sha256 "e9d8240cda4167012847e9326819422aecfd075b7ce74930e7ad322239d7f3ae"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/astrona-io/astrona-cli/releases/download/v0.4.3/astrona-linux-arm64"
      sha256 "02d1f7071494f6b9b7f90bcf609e0f1ba181b0d0cd912f85b90d5a81507f1f06"
    end
    on_intel do
      url "https://github.com/astrona-io/astrona-cli/releases/download/v0.4.3/astrona-linux-amd64"
      sha256 "37fae2eb24dc56293fb33419348425dc5ab0a0216255cb64999ffc026c32c762"
    end
  end

  def install
    # A bare download isn't executable yet, and astrona runs below to
    # generate its completions and man pages.
    binary = Dir["astrona-*"].first
    chmod 0755, binary
    bin.install binary => "astrona"
    generate_completions_from_executable(bin/"astrona", "completion")
    system bin/"astrona", "docgen", "--man", "--output", buildpath/"man"
    man1.install Dir[buildpath/"man/*.1"]
  end

  def caveats
    <<~EOS
      kind needs a container engine — Docker or Podman:
        brew install podman && podman machine init && podman machine start
      or Docker Desktop. `astrona check` lists anything else that's missing.

      Upgrade with `brew upgrade astrona` (`astrona upgrade` runs it for you).
      `brew uninstall astrona` leaves ~/.astrona (labs, results, approvals);
      destroy running labs first: astrona destroy <lab>
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/astrona --version")
    assert_match "astrona-run", shell_output("man -P cat #{man1}/astrona-run.1")
    assert_match "__start_astrona", (bash_completion/"astrona").read
  end
end
